UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Long-serving Republican rated among the Assembly''s most conservative members (92% conservative ranking). While no explicit Israel statement was found, his party alignment and conservative profile strongly suggest support for Israel, consistent with near-universal Republican support for Israel in NY.', summary = 'Ballotpedia (https://ballotpedia.org/Stephen_Hawley) notes Republican/Conservative party affiliations. LegiStorm (https://www.legistorm.com/person/bio/196406/Stephen_M_Hawley.html) notes 92% conservative ranking. The October 2023 "NY Legislators Stand with Israel" letter PDF exists (https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf) but full signatory list could not be confirmed through search.', updated_at = NOW() WHERE person_id = 202 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
