UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Republican who previously served as US Representative (NY-23, 2022-2023). As a former member of Congress, he would have been exposed to Israel-related votes. His Republican affiliation and congressional background strongly suggest pro-Israel positioning, though no explicit NY Assembly-level statement was found.', summary = 'Wikipedia (https://en.wikipedia.org/wiki/Joe_Sempolinski) confirms congressional service. Ballotpedia (https://ballotpedia.org/Joe_Sempolinski) and campaign site (https://joesempolinski.com/) reviewed. No explicit Israel statements found at state level.', updated_at = NOW() WHERE person_id = 211 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Represents Upper East Side (District 4), a district with a significant Jewish community. Daughter of former Congresswoman Carolyn Maloney, who had strong pro-Israel positions and deep Jewish community support. While Virginia Maloney''s own explicit statements were not found, her district demographics and family political background suggest pro-Israel leanings.', summary = 'Patch profile (https://patch.com/new-york/upper-east-side-nyc/election-q-meet-upper-east-side-candidate-virginia-maloney). PoliticsNY (https://politicsny.com/2022/06/23/maloney-peels-off-nadlers-jewish-support-in-redrawn-12th-congressional-district-primary/) documents Carolyn Maloney''s strong Jewish community support.', updated_at = NOW() WHERE person_id = 217 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Represents Flushing, a district with a significant Jewish community presence. Has engaged with the Queens Jewish community, making a "Jewish pitch" during her council run. Previously staffed for Rep. Grace Meng in constituent services. Her outreach to the Jewish community and district demographics suggest pro-Israel leanings.', summary = 'Queens Jewish Link (https://www.queensjewishlink.com/index.php/local/20-community-corner/by-sergey-kadinsky/4464-sandra-ung-makes-jewish-pitch-in-council-run) documents her Jewish community engagement. Wikipedia (https://en.wikipedia.org/wiki/Sandra_Ung) notes her background.', updated_at = NOW() WHERE person_id = 233 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Has actively hosted forums on combating antisemitism in partnership with the Simon Wiesenthal Center and engaged with the Queens Jewish community. Co-sponsored antisemitism-related legislation. Her proactive stance against antisemitism, engagement with Jewish organizations, and district in eastern Queens suggest support for Israel.', summary = 'Queens Jewish Link (https://www.queensjewishlink.com/index.php/local/26-community-corner/8332-council-member-linda-lee-hosts-neighborhood-forum-to-explore-impact-of-hate-and-extremism-on-the-community) and QNS (https://qns.com/2023/03/forum-impact-hate-antisemitism-community/) document her March 2023 antisemitism forum. Queens Chronicle (https://www.qchron.com/editions/queenswide/council-bills-zeroing-in-on-antisemitism/article_64eca29e-a960-5e4c-91b8-3e6f42a6e09f.html) covers her antisemitism l', updated_at = NOW() WHERE person_id = 236 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
UPDATE positions SET stance = 'support', confidence = 'inferred', rationale = 'Participated in a 2015 JCRC/UJA-sponsored delegation trip to Israel despite significant community opposition. Her willingness to go on this pro-Israel trip, organized by major Jewish organizations, indicates a supportive stance toward Israel.', summary = 'JVP (https://www.jewishvoiceforpeace.org/2015/01/12/community-leaders-launch-campaign-against-city-council-delegation-to-israel/) and Mondoweiss (https://mondoweiss.net/2015/01/coalition-community-delegation/) document her participation in the JCRC Israel delegation. Middle East Eye (https://www.middleeasteye.net/features/new-york-council-trip-highlights-ties-between-israel-and-us-cities) also covered the trip.', updated_at = NOW() WHERE person_id = 254 AND topic_id = (SELECT id FROM topics WHERE slug = 'israel') AND assessment_type = 'ai';
